import React, { useState, useEffect } from 'react';
import Navbar from '../components/Navbar';
import { 
  FaPlus, FaTrash, FaCalendarAlt, FaClock, FaBrain, 
  FaChartLine, FaCheckCircle, FaCircle, FaBook, FaClipboardList,
  FaBriefcase, FaUsers, FaFire, FaSmile, FaMeh, FaFrown
} from 'react-icons/fa';

function AcademicLoad() {
  const [items, setItems] = useState([]);
  const [showAddForm, setShowAddForm] = useState(false);
  const [aiInsight, setAiInsight] = useState('');
  const [completionRate, setCompletionRate] = useState(0);
  const [stressLevel, setStressLevel] = useState('medium');
  const [newItem, setNewItem] = useState({
    title: '',
    type: 'exam',
    dueDate: '',
    dueTime: '',
    priority: 'medium',
    completed: false
  });

  useEffect(() => {
    const saved = localStorage.getItem('academicLoad');
    if (saved) {
      const loadedItems = JSON.parse(saved);
      setItems(loadedItems);
      calculateStats(loadedItems);
      generateAIInsight(loadedItems);
    }
  }, []);

  const calculateStats = (taskList) => {
    const completed = taskList.filter(i => i.completed).length;
    const rate = taskList.length > 0 ? Math.round((completed / taskList.length) * 100) : 0;
    setCompletionRate(rate);
    
    const pendingHigh = taskList.filter(i => !i.completed && i.priority === 'high').length;
    if (pendingHigh >= 3) setStressLevel('high');
    else if (pendingHigh >= 1) setStressLevel('medium');
    else setStressLevel('low');
  };

  const generateAIInsight = (taskList) => {
    const pending = taskList.filter(i => !i.completed);
    const highPriority = pending.filter(i => i.priority === 'high');
    const dueSoon = pending.filter(i => {
      if (!i.dueDate) return false;
      const dueDate = new Date(i.dueDate);
      const today = new Date();
      const diffTime = dueDate - today;
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      return diffDays <= 3 && diffDays >= 0;
    });
    
    let insight = '';
    if (pending.length === 0) {
      insight = '🎉 All tasks completed! Take a break.';
    } else if (highPriority.length >= 2) {
      insight = `🧠 ${highPriority.length} high-priority tasks. Try a 25-min focus session.`;
    } else if (dueSoon.length > 0) {
      insight = `📅 ${dueSoon.length} task(s) due soon. Stay on track!`;
    } else if (pending.length >= 5) {
      insight = `📚 Heavy workload. Take short breaks to avoid burnout.`;
    } else {
      insight = `💡 You're making progress! Keep going.`;
    }
    setAiInsight(insight);
  };

  const saveToLocal = (newItems) => {
    setItems(newItems);
    localStorage.setItem('academicLoad', JSON.stringify(newItems));
    calculateStats(newItems);
    generateAIInsight(newItems);
  };

  const addItem = () => {
    if (newItem.title && newItem.dueDate) {
      const newItems = [...items, { ...newItem, id: Date.now() }];
      saveToLocal(newItems);
      setNewItem({ title: '', type: 'exam', dueDate: '', dueTime: '', priority: 'medium', completed: false });
      setShowAddForm(false);
    }
  };

  const toggleComplete = (id) => {
    const newItems = items.map(item => item.id === id ? { ...item, completed: !item.completed } : item);
    saveToLocal(newItems);
  };

  const deleteItem = (id) => {
    const newItems = items.filter(item => item.id !== id);
    saveToLocal(newItems);
  };

  const getTypeIcon = (type) => {
    switch(type) {
      case 'exam': return <FaBook size={12} color="#e74c3c" />;
      case 'assignment': return <FaClipboardList size={12} color="#f39c12" />;
      case 'club': return <FaUsers size={12} color="#2ecc71" />;
      case 'work': return <FaBriefcase size={12} color="#3498db" />;
      default: return <FaBriefcase size={12} />;
    }
  };

  const getTypeLabel = (type) => {
    switch(type) {
      case 'exam': return 'Exam';
      case 'assignment': return 'Assignment';
      case 'club': return 'Club';
      case 'work': return 'Work';
      default: return 'Task';
    }
  };

  const getPriorityColor = (priority) => {
    if (priority === 'high') return '#e74c3c';
    if (priority === 'medium') return '#f39c12';
    return '#2ecc71';
  };

  const upcomingItems = items.filter(i => !i.completed).sort((a,b) => new Date(a.dueDate) - new Date(b.dueDate));
  const completedItems = items.filter(i => i.completed);
  
  const getStressIcon = () => {
    if (stressLevel === 'high') return <FaFrown size={16} color="#e74c3c" />;
    if (stressLevel === 'medium') return <FaMeh size={16} color="#f39c12" />;
    return <FaSmile size={16} color="#2ecc71" />;
  };

  const types = [
    { value: 'exam', label: 'Exam', color: '#e74c3c' },
    { value: 'assignment', label: 'Assignment', color: '#f39c12' },
    { value: 'club', label: 'Club', color: '#2ecc71' },
    { value: 'work', label: 'Work', color: '#3498db' },
  ];

  return (
    <div style={styles.container}>
      <Navbar />
      <div style={styles.navSpacer} />
      
      <div style={styles.content}>
        {/* Header */}
        <div style={styles.header}>
          <h1 style={styles.title}>📚 Academic Load</h1>
        </div>

        {/* AI Insight - Small */}
        <div style={styles.aiBar}>
          <FaBrain size={14} color="#667eea" />
          <span style={styles.aiText}>{aiInsight || "Loading..."}</span>
        </div>

        {/* Stats Row - Compact */}
        <div style={styles.statsRow}>
          <div style={styles.statBlock}>
            <FaFire size={14} color="#e74c3c" />
            <span style={styles.statNum}>{items.filter(i => !i.completed).length}</span>
            <span style={styles.statLabel}>Pending</span>
          </div>
          <div style={styles.statBlock}>
            <FaCheckCircle size={14} color="#2ecc71" />
            <span style={styles.statNum}>{completedItems.length}</span>
            <span style={styles.statLabel}>Done</span>
          </div>
          <div style={styles.statBlock}>
            <FaChartLine size={14} color="#3498db" />
            <span style={styles.statNum}>{items.length}</span>
            <span style={styles.statLabel}>Total</span>
          </div>
          <div style={styles.statBlock}>
            {getStressIcon()}
            <span style={styles.statNum}>{completionRate}%</span>
            <span style={styles.statLabel}>Progress</span>
          </div>
        </div>

        {/* Add Task Button - Prominent but not bulky */}
        <button onClick={() => setShowAddForm(true)} style={styles.addBtn}>
          <FaPlus size={12} /> Add Task
        </button>

        {/* Upcoming Tasks */}
        <div style={styles.taskSection}>
          <h3 style={styles.sectionTitle}>⏰ Upcoming</h3>
          {upcomingItems.length === 0 && <p style={styles.empty}>No pending tasks ✨</p>}
          {upcomingItems.map(item => (
            <div key={item.id} style={{...styles.taskItem, borderLeftColor: getPriorityColor(item.priority)}}>
              <div style={styles.taskLeft}>
                <div onClick={() => toggleComplete(item.id)} style={styles.check}>
                  {item.completed ? <FaCheckCircle color="#2ecc71" size={16} /> : <FaCircle color="#ccc" size={16} />}
                </div>
                <span style={styles.taskType}>{getTypeIcon(item.type)}</span>
                <div style={styles.taskInfo}>
                  <span style={styles.taskName}>{getTypeLabel(item.type)}: {item.title}</span>
                  <span style={styles.taskDate}><FaCalendarAlt size={10} /> {new Date(item.dueDate).toLocaleDateString()}</span>
                </div>
              </div>
              <button onClick={() => deleteItem(item.id)} style={styles.delBtn}><FaTrash size={12} /></button>
            </div>
          ))}
        </div>

        {/* Completed Tasks - Collapsible */}
        {completedItems.length > 0 && (
          <div style={styles.taskSection}>
            <h3 style={styles.sectionTitle}>✅ Completed</h3>
            {completedItems.slice(0, 3).map(item => (
              <div key={item.id} style={{...styles.taskItem, opacity: 0.6, background: '#f0fff0'}}>
                <div style={styles.taskLeft}>
                  <div onClick={() => toggleComplete(item.id)} style={styles.check}>
                    <FaCheckCircle color="#2ecc71" size={16} />
                  </div>
                  <span style={styles.taskType}>{getTypeIcon(item.type)}</span>
                  <div style={styles.taskInfo}>
                    <span style={{...styles.taskName, textDecoration: 'line-through'}}>{item.title}</span>
                  </div>
                </div>
                <button onClick={() => deleteItem(item.id)} style={styles.delBtn}><FaTrash size={12} /></button>
              </div>
            ))}
            {completedItems.length > 3 && <p style={styles.more}>+{completedItems.length - 3} more</p>}
          </div>
        )}

        {/* Add Task Modal - Compact */}
        {showAddForm && (
          <div style={styles.modal} onClick={() => setShowAddForm(false)}>
            <div style={styles.modalBox} onClick={(e) => e.stopPropagation()}>
              <h3 style={styles.modalTitle}>➕ New Task</h3>
              
              <input 
                type="text" 
                placeholder="Task name" 
                value={newItem.title} 
                onChange={(e) => setNewItem({...newItem, title: e.target.value})} 
                style={styles.modalInput} 
              />
              
              <div style={styles.typeRow}>
                {types.map(t => (
                  <button 
                    key={t.value} 
                    onClick={() => setNewItem({...newItem, type: t.value})} 
                    style={{...styles.typeChip, background: newItem.type === t.value ? t.color : '#f0f0f0', color: newItem.type === t.value ? 'white' : '#555'}}
                  >
                    {t.label}
                  </button>
                ))}
              </div>
              
              <input 
                type="date" 
                value={newItem.dueDate} 
                onChange={(e) => setNewItem({...newItem, dueDate: e.target.value})} 
                style={styles.modalInput} 
              />
              
              <input 
                type="time" 
                value={newItem.dueTime} 
                onChange={(e) => setNewItem({...newItem, dueTime: e.target.value})} 
                style={styles.modalInput} 
              />
              
              <div style={styles.priorityRow}>
                <button onClick={() => setNewItem({...newItem, priority: 'low'})} style={{...styles.priorityChip, background: newItem.priority === 'low' ? '#2ecc71' : '#f0f0f0', color: newItem.priority === 'low' ? 'white' : '#555'}}>Low</button>
                <button onClick={() => setNewItem({...newItem, priority: 'medium'})} style={{...styles.priorityChip, background: newItem.priority === 'medium' ? '#f39c12' : '#f0f0f0', color: newItem.priority === 'medium' ? 'white' : '#555'}}>Medium</button>
                <button onClick={() => setNewItem({...newItem, priority: 'high'})} style={{...styles.priorityChip, background: newItem.priority === 'high' ? '#e74c3c' : '#f0f0f0', color: newItem.priority === 'high' ? 'white' : '#555'}}>High</button>
              </div>
              
              <div style={styles.modalActions}>
                <button onClick={addItem} style={styles.saveBtn}>Save</button>
                <button onClick={() => setShowAddForm(false)} style={styles.cancelBtn}>Cancel</button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

